-- 40_qc_fact_def_seed.sql
-- 质控：事实层定义（quality_fact_def）补数（达梦 DM8）
--
-- 背景（线上真实故障）：
--   出现过「指标表 127 条、事实层表 0 条」的半空状态。DSL 以 db 为配置真源时
--   读到 0 个事实层，而每条指标都要按 fact_name 找到事实层才能编译，于是看板上
--   每次触发计算都直接 FAILED，耗时只有几十毫秒（压根没开始算）：
--     [质控] DSL 加载完成（真源 db）：数据源 2 个，事实层 0 个，指标 127 条
--     [质控] 计算完成 状态=FAILED 成功=0 失败=2 耗时=41ms
--   成因通常是配置快照类脚本「先 DELETE 后 INSERT」，INSERT 未成功时留下空表。
--
-- 本脚本做什么：
--   仅当事实层表为空时，导入出厂的 10 条事实层定义；表里有数据则不动，
--   绝不覆盖现场已调整过的配置。可重复执行。
--
-- 数据来源：与 jar 内 classpath:quality/facts/*.yaml 一致的出厂定义快照
--           （取自 27_restore_config_snapshot.sql 的同名段落）。
--
-- 还要不要补代码：
--   需要。代码侧已修（QualityDslLoader 按层补种 + 事实层为空时回退 YAML），
--   新包启动会自动补种，不必执行本脚本。本脚本用于「不想等新包、先恢复线上」
--   的场景，执行完重启服务即可。
--
-- 依赖：10_quality_config.sql（表与唯一索引 uk_qfd_name 已建）
--
-- 执行方式（SYSDBA）：
--   disql SYSDBA/口令@host:port
--   SQL> start /opt/zing-doctor/sql/40_qc_fact_def_seed.sql
-- =====================================================================

DECLARE
    v_count INT;
BEGIN
    SELECT COUNT(*) INTO v_count FROM "zing_doctor_db_prod"."quality_fact_def";

    IF v_count = 0 THEN
        INSERT INTO "zing_doctor_db_prod"."quality_fact_def" ("id", "fact_name", "domain_code", "status", "source_table", "alias", "patient_key", "in_hospital_no_key", "patient_name_key", "depart_key", "select_cols", "derive_cols", "where_conds", "group_cols", "note", "operator", "create_time", "update_time") VALUES (178949847996900, 'fact_sepsis_bundle', '脓毒症_感染性休克', 'ACTIVE', 'patient_info', 'pi', 'patient_id', 'in_hospital_no', 'patient_name', 'depart_code', '["pi.id AS patient_id","pi.in_hospital_no AS in_hospital_no","pi.name AS patient_name","pi.gender AS gender","pi.depart_code AS depart_code","pi.in_depart_time AS in_depart_time","pi.out_depart_time AS out_depart_time","pi.bed_code AS bed_code","CAST(pi.diagnosis_content AS VARCHAR(2000)) AS diagnosis_content"]', '["CASE WHEN pi.is_sepsis_shock = 1 THEN 1 ELSE 0 END AS sepsis_shock","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND d.diag_name LIKE ''%感染性休克%'' AND d.diag_time IS NOT NULL AND d.diag_time < pi.in_depart_time) THEN 1 ELSE 0 END AS pre_icu_shock","CASE WHEN pi.is_sepsis_shock = 1 AND NOT EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND d.diag_name LIKE ''%感染性休克%'' AND d.diag_time IS NOT NULL AND d.diag_time < pi.in_depart_time) THEN 1 ELSE 0 END AS in_icu_shock","CASE WHEN REGEXP_LIKE(TRIM(pi.age), ''^[0-9]{1,3}$'') THEN CAST(TRIM(pi.age) AS INT) END AS age_num","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_lis_item\" li WHERE li.in_hospital_no = pi.in_hospital_no AND li.del_flag = 0 AND li.lis_item_name LIKE ''%乳酸%'' AND li.check_time IS NOT NULL AND DATEDIFF(MINUTE, pi.in_depart_time, li.check_time) BETWEEN 0 AND 60) THEN 1 ELSE 0 END AS lactate_1h","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_lis_item\" li WHERE li.in_hospital_no = pi.in_hospital_no AND li.del_flag = 0 AND li.lis_item_name LIKE ''%血培养%'' AND li.check_time IS NOT NULL AND DATEDIFF(MINUTE, pi.in_depart_time, li.check_time) BETWEEN 0 AND 60) THEN 1 ELSE 0 END AS culture_1h","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice\" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = ''1'' AND pa.type_code = ''drug'' AND pa.start_time IS NOT NULL AND DATEDIFF(MINUTE, pi.in_depart_time, pa.start_time) BETWEEN 0 AND 60 AND (pa.name LIKE ''%头孢%'' OR pa.name LIKE ''%培南%'' OR pa.name LIKE ''%万古霉素%'' OR pa.name LIKE ''%利奈唑胺%'' OR pa.name LIKE ''%替考拉宁%'' OR pa.name LIKE ''%达托霉素%'' OR pa.name LIKE ''%左氧氟沙星%'' OR pa.name LIKE ''%莫西沙星%'' OR pa.name LIKE ''%环丙沙星%'' OR pa.name LIKE ''%阿奇霉素%'' OR pa.name LIKE ''%阿米卡星%'' OR pa.name LI' || 'KE ''%庆大霉素%'' OR pa.name LIKE ''%替加环素%'' OR pa.name LIKE ''%多黏菌素%'' OR pa.name LIKE ''%氟康唑%'' OR pa.name LIKE ''%伏立康唑%'' OR pa.name LIKE ''%卡泊芬净%'' OR pa.name LIKE ''%米卡芬净%'' OR pa.name LIKE ''%甲硝唑%'' OR pa.name LIKE ''%青霉素%'' OR pa.name LIKE ''%阿莫西林%'' OR pa.name LIKE ''%氨苄西林%'' OR pa.name LIKE ''%哌拉西林%'' OR pa.name LIKE ''%氨曲南%'' OR pa.name LIKE ''%磷霉素%'' OR pa.name LIKE ''%利福平%'' OR pa.name LIKE ''%磺胺%'' OR pa.name LIKE ''%新诺明%'')) THEN 1 ELSE 0 END AS abx_1h","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_lis_item\" li WHERE li.in_hospital_no = pi.in_hospital_no AND li.del_flag = 0 AND li.lis_item_name LIKE ''%乳酸%'' AND li.check_time IS NOT NULL AND DATEDIFF(MINUTE, pi.in_depart_time, li.check_time) BETWEEN 0 AND 180) THEN 1 ELSE 0 END AS lactate_3h","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_lis_item\" li WHERE li.in_hospital_no = pi.in_hospital_no AND li.del_flag = 0 AND li.lis_item_name LIKE ''%血培养%'' AND li.check_time IS NOT NULL AND DATEDIFF(MINUTE, pi.in_depart_time, li.check_time) BETWEEN 0 AND 180) THEN 1 ELSE 0 END AS culture_3h","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice\" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = ''1'' AND pa.type_code = ''drug'' AND pa.start_time IS NOT NULL AND DATEDIFF(MINUTE, pi.in_depart_time, pa.start_time) BETWEEN 0 AND 180 AND (pa.name LIKE ''%头孢%'' OR pa.name LIKE ''%培南%'' OR pa.name LIKE ''%万古霉素%'' OR pa.name LIKE ''%利奈唑胺%'' OR pa.name LIKE ''%替考拉宁%'' OR pa.name LIKE ''%达托霉素%'' OR pa.name LIKE ''%左氧氟沙星%'' OR pa.name LIKE ''%莫西沙星%'' OR pa.name LIKE ''%环丙沙星%'' OR pa.name LIKE ''%阿奇霉素%'' OR pa.name LIKE ''%阿米卡星%'' OR pa.name LIKE ''%庆大霉素%'' OR pa.name LIKE ''%替加环素%'' OR pa.name LIKE ''%多黏菌素%'' OR pa.name LIKE ''%氟康唑%'' OR pa.name LIKE ''%伏立康唑%'' OR pa.name LIKE ''%卡泊芬净%'' OR pa.name LIKE ''%米卡芬净%'' OR pa.name LIKE ''%甲硝唑%'' OR pa.name LIKE ''%青霉素%'' OR pa.name LIKE ''%阿莫西林%'' OR pa.name LIKE ''%氨苄西林%'' OR pa.name' || ' LIKE ''%哌拉西林%'' OR pa.name LIKE ''%氨曲南%'' OR pa.name LIKE ''%磷霉素%'' OR pa.name LIKE ''%利福平%'' OR pa.name LIKE ''%磺胺%'' OR pa.name LIKE ''%新诺明%'')) THEN 1 ELSE 0 END AS abx_3h","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice\" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = ''1'' AND pa.type_code = ''drug'' AND pa.start_time IS NOT NULL AND DATEDIFF(MINUTE, pi.in_depart_time, pa.start_time) BETWEEN 0 AND 360 AND (pa.name LIKE ''%去甲肾上腺素%'' OR pa.name LIKE ''%肾上腺素%'' OR pa.name LIKE ''%多巴胺%'' OR pa.name LIKE ''%多巴酚丁胺%'' OR pa.name LIKE ''%血管加压素%'' OR pa.name LIKE ''%垂体后叶%'')) THEN 1 ELSE 0 END AS vaso_6h","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%血流感染%'' OR d.diag_name LIKE ''%菌血症%'')) THEN 1 ELSE 0 END AS site_blood","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%导管相关%'' OR d.diag_name LIKE ''%CRBSI%'')) THEN 1 ELSE 0 END AS site_crbsi","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%腹腔感染%'' OR d.diag_name LIKE ''%腹膜炎%'')) THEN 1 ELSE 0 END AS site_abdomen","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%泌尿%'' OR d.diag_name LIKE ''%尿路%'')) THEN 1 ELSE 0 END AS site_urinary","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%中枢神经%'' OR d.diag_name LIKE ''%颅内感染%'' OR d.diag_name LIKE ''%脑膜炎%'')) THEN 1 ELSE 0 END AS site_cns","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\' || '" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%肺部感染%'' OR d.diag_name LIKE ''%肺炎%'')) THEN 1 ELSE 0 END AS site_lung","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%胆道%'' OR d.diag_name LIKE ''%胆管炎%'' OR d.diag_name LIKE ''%胆囊炎%'')) THEN 1 ELSE 0 END AS site_biliary","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%胃肠道%'' OR d.diag_name LIKE ''%肠炎%'' OR d.diag_name LIKE ''%消化道感染%'')) THEN 1 ELSE 0 END AS site_gi","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND d.diag_name LIKE ''%骨髓%'') THEN 1 ELSE 0 END AS site_marrow","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%皮肤软组织%'' OR d.diag_name LIKE ''%蜂窝织炎%'')) THEN 1 ELSE 0 END AS site_skin","CASE WHEN (SELECT COUNT(1) FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%血流感染%'' OR d.diag_name LIKE ''%菌血症%'' OR d.diag_name LIKE ''%导管相关%'' OR d.diag_name LIKE ''%CRBSI%'' OR d.diag_name LIKE ''%腹腔感染%'' OR d.diag_name LIKE ''%腹膜炎%'' OR d.diag_name LIKE ''%泌尿%'' OR d.diag_name LIKE ''%尿路%'' OR d.diag_name LIKE ''%中枢神经%'' OR d.diag_name LIKE ''%颅内感染%'' OR d.diag_name LIKE ''%脑膜炎%'' OR d.diag_name LIKE ''%肺部感染%'' OR d.diag_name LIKE ''%肺炎%'' OR d.diag_name LIKE ''%胆道%'' OR d.diag_name LIKE ''%胆管炎%'' OR d.diag_name LIKE ''%胆囊炎%'' OR d.diag_name LIKE ''%胃肠道%'' OR d.diag_name LIKE ''%肠炎%'' OR d.diag_name LIKE ''%消化道感染%'' OR d.diag_name LIKE ''%骨髓%'' OR d.diag_name LIKE ''%皮肤软组织%'' OR d.diag_name LIKE ''%蜂窝织炎%'')) = 0 THEN 1 ELSE 0 E' || 'ND AS site_none","CASE WHEN pi.out_vest_type = 3 AND pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS died_in_period","CASE WHEN pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS out_in_period"]', '["pi.del_flag = 0","pi.in_depart_time IS NOT NULL","pi.in_depart_time < :periodEnd","(pi.out_depart_time IS NULL OR pi.out_depart_time >= :periodStart)"]', '[]', '感染性休克识别 + 1h/3h/6h 集束化要素（乳酸/血培养/抗菌药/血管活性药）', 'seed', TIMESTAMP '2026-09-16 02:54:39', TIMESTAMP '2026-09-16 02:54:39');
        INSERT INTO "zing_doctor_db_prod"."quality_fact_def" ("id", "fact_name", "domain_code", "status", "source_table", "alias", "patient_key", "in_hospital_no_key", "patient_name_key", "depart_key", "select_cols", "derive_cols", "where_conds", "group_cols", "note", "operator", "create_time", "update_time") VALUES (178949847999000, 'fact_assessment', '评估依从', 'ACTIVE', 'patient_info', 'pi', 'patient_id', 'in_hospital_no', 'patient_name', 'depart_code', '["pi.id AS patient_id","pi.in_hospital_no AS in_hospital_no","pi.name AS patient_name","pi.depart_code AS depart_code","pi.in_depart_time AS in_depart_time","pi.out_depart_time AS out_depart_time","pi.bed_code AS bed_code","CAST(pi.diagnosis_content AS VARCHAR(2000)) AS diagnosis_content"]', '["CASE WHEN DATEDIFF(HOUR, pi.in_depart_time, CASE WHEN (pi.out_depart_time IS NULL OR pi.out_depart_time > :periodEnd) THEN :periodEnd ELSE pi.out_depart_time END) > 48 THEN 1 ELSE 0 END AS stay_gt_48h","CASE WHEN pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS out_in_period","CASE WHEN pi.out_vest_type = 3 AND pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS died_in_period","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_observe_module_item_record\" i WHERE i.patient_id = pi.id AND i.del_flag = 0 AND i.item_code = ''oi_ttpf'' and i.item_value is not null) THEN 1 ELSE 0 END AS ttpf","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_observe_module_item_record\" i WHERE i.patient_id = pi.id AND i.del_flag = 0 AND i.item_code = ''oi_rass'' and i.item_value is not null) THEN 1 ELSE 0 END AS rass","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_observe_module_item\" i WHERE i.patient_id = pi.id AND i.del_flag = 0 AND (i.item_name LIKE ''%意识%'' OR i.item_name LIKE ''%格拉斯哥%'' OR i.item_name LIKE ''%GCS%'')) THEN 1 ELSE 0 END AS consciousness_assessed","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%脑出血%'' OR d.diag_name LIKE ''%脑梗死%'' OR d.diag_name LIKE ''%颅脑损伤%'' OR d.diag_name LIKE ''%脑外伤%'' OR d.diag_name LIKE ''%蛛网膜下腔出血%'' OR d.diag_name LIKE ''%缺氧性脑病%'')) THEN 1 ELSE 0 END AS abi","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice\" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = ''1'' AND pa.start_time IS NOT NULL AND DATEDIFF(HOUR, pi.in_depart_time, pa.start_time) BETWEEN 0 AND 48 AND (pa.name LIKE ''%肠内营养%'' OR pa.name LIKE ''%鼻饲%'' OR pa.name LIKE ''%肠内%'' OR pa.name LIKE ''%能全力%'' OR pa.name LIKE ''%百普力%'' OR pa.name LIKE ''%瑞代%'' OR pa.name LIKE ''%瑞先%''' || ')) THEN 1 ELSE 0 END AS en_48h"]', '["pi.del_flag = 0","pi.in_depart_time IS NOT NULL","pi.out_depart_time IS NOT NULL","pi.out_depart_time < :periodEnd","pi.out_depart_time >= :periodStart"]', '[]', '镇静/镇痛/意识评估与 48h 内肠内营养启动', '系统管理员', TIMESTAMP '2026-09-16 02:54:39', TIMESTAMP '2026-09-17 17:18:23');
        INSERT INTO "zing_doctor_db_prod"."quality_fact_def" ("id", "fact_name", "domain_code", "status", "source_table", "alias", "patient_key", "in_hospital_no_key", "patient_name_key", "depart_key", "select_cols", "derive_cols", "where_conds", "group_cols", "note", "operator", "create_time", "update_time") VALUES (178949847999500, 'fact_ards', 'ARDS专项', 'ACTIVE', 'patient_info', 'pi', 'patient_id', 'in_hospital_no', 'patient_name', 'depart_code', '["pi.id AS patient_id","pi.in_hospital_no AS in_hospital_no","pi.name AS patient_name","pi.gender AS gender","pi.depart_code AS depart_code","pi.in_depart_time AS in_depart_time","pi.out_depart_time AS out_depart_time","pi.bed_code AS bed_code","CAST(pi.diagnosis_content AS VARCHAR(2000)) AS diagnosis_content"]', '["CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%ARDS%'' OR d.diag_name LIKE ''%急性呼吸窘迫%'')) THEN 1 ELSE 0 END AS ards","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%ARDS%'' OR d.diag_name LIKE ''%急性呼吸窘迫%'') AND d.diag_name LIKE ''%轻度%'') THEN 1 ELSE 0 END AS ards_mild","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%ARDS%'' OR d.diag_name LIKE ''%急性呼吸窘迫%'') AND d.diag_name LIKE ''%中度%'') THEN 1 ELSE 0 END AS ards_moderate","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%ARDS%'' OR d.diag_name LIKE ''%急性呼吸窘迫%'') AND d.diag_name LIKE ''%重度%'') THEN 1 ELSE 0 END AS ards_severe","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice\" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = ''1'' AND (pa.name LIKE ''%气管插管%'' OR pa.name LIKE ''%机械通气%'' OR pa.name LIKE ''%呼吸机%'')) THEN 1 ELSE 0 END AS intubated","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice\" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = ''1'' AND (pa.name LIKE ''%无创%'' OR pa.name LIKE ''%BiPAP%'' OR pa.name LIKE ''%CPAP%'' OR pa.name LIKE ''%无创呼吸机%'')) THEN 1 ELSE 0 END AS niv","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice\" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = ''1'' AND (pa.name LIKE ''%高流量%'' OR pa.name LIKE ''%HFNC%'' OR pa.name LIKE ''%经鼻高流量%'')) THEN 1 ELSE 0 END AS hfnc","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice\"' || ' pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = ''1'' AND pa.name LIKE ''%俯卧位%'') OR EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_observe_module_item\" i WHERE i.patient_id = pi.id AND i.del_flag = 0 AND i.item_name LIKE ''%俯卧位%'') THEN 1 ELSE 0 END AS prone","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice\" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = ''1'' AND pa.type_code = ''drug'' AND (pa.name LIKE ''%顺阿曲库铵%'' OR pa.name LIKE ''%阿曲库铵%'' OR pa.name LIKE ''%维库溴铵%'' OR pa.name LIKE ''%罗库溴铵%'' OR pa.name LIKE ''%哌库溴铵%'')) THEN 1 ELSE 0 END AS muscle_relaxant","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice\" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = ''1'' AND (pa.name LIKE ''%ECMO%'' OR pa.name LIKE ''%体外膜肺%'')) THEN 1 ELSE 0 END AS ecmo","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND d.diag_name LIKE ''%细菌性肺炎%'') THEN 1 ELSE 0 END AS cause_bacterial_pneumonia","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%病毒性肺炎%'' OR d.diag_name LIKE ''%病毒肺炎%'')) THEN 1 ELSE 0 END AS cause_viral_pneumonia","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%真菌性肺炎%'' OR d.diag_name LIKE ''%肺真菌%'')) THEN 1 ELSE 0 END AS cause_fungal_pneumonia","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND d.diag_name LIKE ''%吸入性肺炎%'') THEN 1 ELSE 0 END AS cause_aspiration","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_' || 'flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%肺挫伤%'' OR d.diag_name LIKE ''%肺挫裂伤%'')) THEN 1 ELSE 0 END AS cause_contusion","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%脓毒症%'' OR d.diag_name LIKE ''%感染性休克%'') AND d.diag_name NOT LIKE ''%肺炎%'') THEN 1 ELSE 0 END AS cause_extrapulmonary_infection","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%多发伤%'' OR d.diag_name LIKE ''%创伤性休克%'')) THEN 1 ELSE 0 END AS cause_extrapulmonary_trauma","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%重症胰腺炎%'' OR d.diag_name LIKE ''%急性胰腺炎%'')) THEN 1 ELSE 0 END AS cause_pancreatitis","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%大量输血%'' OR d.diag_name LIKE ''%输血相关%'')) THEN 1 ELSE 0 END AS cause_massive_transfusion","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%体外循环%'' OR d.diag_name LIKE ''%心脏术后%'')) THEN 1 ELSE 0 END AS cause_cardiopulmonary_bypass","CASE WHEN pi.gender = ''男'' OR pi.gender = ''1'' OR pi.gender = ''M'' THEN 1 ELSE 0 END AS sex_male","CASE WHEN REGEXP_LIKE(TRIM(pi.age), ''^[0-9]{1,3}$'') THEN CAST(TRIM(pi.age) AS INT) END AS age_num","CASE WHEN pi.out_vest_type = 3 AND pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS died_in_period"]', '["pi.del_flag = 0","pi.in_depart_time IS NOT NULL","pi.in_depart_time < :periodEnd","(pi.out_depart_time IS NULL OR pi.out_depart_time >= :periodStart)"]', '[]', 'ARDS 人群/分度/病因/呼吸支持方式', 'seed', TIMESTAMP '2026-09-16 02:54:39', TIMESTAMP '2026-09-16 02:54:39');
        INSERT INTO "zing_doctor_db_prod"."quality_fact_def" ("id", "fact_name", "domain_code", "status", "source_table", "alias", "patient_key", "in_hospital_no_key", "patient_name_key", "depart_key", "select_cols", "derive_cols", "where_conds", "group_cols", "note", "operator", "create_time", "update_time") VALUES (178949848000100, 'fact_patient_stay', '患者流转', 'ACTIVE', 'patient_info', 'pi', 'patient_id', 'in_hospital_no', 'patient_name', 'depart_code', '["pi.id AS patient_id","pi.in_hospital_no AS in_hospital_no","pi.name AS patient_name","pi.gender AS gender","pi.bed_code AS bed_code","pi.age AS age","pi.depart_code AS depart_code","pi.ward_name AS ward_name","pi.out_vest_type AS out_vest_type","pi.charge_doctor_name AS charge_doctor_name","pi.in_depart_time AS in_depart_time","pi.out_depart_time AS out_depart_time","pi.out_hospital_time AS out_hospital_time","CAST(pi.diagnosis_content AS VARCHAR(2000)) AS diagnosis_content"]', '["CASE WHEN pi.in_depart_time >= :periodStart THEN 1 ELSE 0 END AS admitted_in_period","CASE WHEN pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS out_in_period","CASE WHEN pi.out_vest_type = 3 THEN 1 ELSE 0 END AS died","CASE WHEN pi.out_vest_type = 3 AND pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS died_in_period","CASE WHEN (pi.out_vest_type IS NULL OR pi.out_vest_type <> 3) AND pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS survived_out_in_period","DATEDIFF(DAY, CASE WHEN pi.in_depart_time < :periodStart THEN :periodStart ELSE pi.in_depart_time END, CASE WHEN (pi.out_depart_time IS NULL OR pi.out_depart_time > :periodEnd) THEN :periodEnd ELSE pi.out_depart_time END) AS stay_days","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%术后%'' OR d.diag_name LIKE ''%手术后%'')) THEN 1 ELSE 0 END AS post_op","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info\" p2 WHERE p2.in_hospital_no = pi.in_hospital_no AND p2.id <> pi.id AND p2.del_flag = 0 AND p2.out_depart_time IS NOT NULL AND p2.out_depart_time < pi.in_depart_time AND DATEDIFF(HOUR, p2.out_depart_time, pi.in_depart_time) <= 48) THEN 1 ELSE 0 END AS readmit_48h"]', '["pi.del_flag = 0","pi.in_depart_time IS NOT NULL","pi.in_depart_time < :periodEnd","(pi.out_depart_time IS NULL OR pi.out_depart_time >= :periodStart)"]', '[]', 'ICU 患者主表；床日按「本周期 ∩ 在院区间」取交集，跨月自动切分', 'unknown', TIMESTAMP '2026-09-16 02:54:39', TIMESTAMP '2026-09-16 19:44:42');
        INSERT INTO "zing_doctor_db_prod"."quality_fact_def" ("id", "fact_name", "domain_code", "status", "source_table", "alias", "patient_key", "in_hospital_no_key", "patient_name_key", "depart_key", "select_cols", "derive_cols", "where_conds", "group_cols", "note", "operator", "create_time", "update_time") VALUES (178949848000500, 'fact_score_resource', '评分_资源', 'ACTIVE', 'apache2_score_record', 'a', 'id', 'in_hospital_no', 'patient_name', 'depart_code', '["a.id AS id","a.patient_id AS patient_id","a.in_hospital_no AS in_hospital_no","a.patient_name AS patient_name","a.depart_code AS depart_code","a.total_score AS total_score","a.mortality_rate AS mortality_rate","a.score_time AS score_time","a.score_type AS score_type"]', '["CASE WHEN a.total_score >= 15 THEN 1 ELSE 0 END AS apache_ge15","(select p2.out_depart_time FROM \"zing_icu_db_prod\".\"patient_info\" p2 WHERE p2.id = a.patient_id)  AS out_depart_time"]', '["a.status = 1","(select p2.out_depart_time FROM \"zing_icu_db_prod\".\"patient_info\" p2 WHERE p2.id = a.patient_id)  >= :periodStart","(select p2.out_depart_time FROM \"zing_icu_db_prod\".\"patient_info\" p2 WHERE p2.id = a.patient_id)  < :periodEnd"]', '[]', 'APACHE II 评分记录；预计病死率取 mortality_rate 均值', 'unknown', TIMESTAMP '2026-09-16 02:54:39', TIMESTAMP '2026-09-16 22:03:27');
        INSERT INTO "zing_doctor_db_prod"."quality_fact_def" ("id", "fact_name", "domain_code", "status", "source_table", "alias", "patient_key", "in_hospital_no_key", "patient_name_key", "depart_key", "select_cols", "derive_cols", "where_conds", "group_cols", "note", "operator", "create_time", "update_time") VALUES (178949848001200, 'fact_staff', '职工_资源', 'PENDING_SOURCE', 'config_staff', 's', 'user_id', 'work_no', 'realname', 'depart_name', '["s.id AS user_id","s.realname AS realname","s.work_no AS work_no","s.depart_name AS depart_name"]', '["CASE WHEN s.post_name LIKE ''%医师%'' THEN 1 ELSE 0 END AS is_doctor","CASE WHEN s.post_name LIKE ''%护士%'' THEN 1 ELSE 0 END AS is_nurse"]', '["s.del_flag = 0"]', '[]', '待接 ICU 医护人员花名册（config_staff：科室 + 岗位）。口径确认后置 ACTIVE 即生效', '系统管理员', TIMESTAMP '2026-09-16 02:54:39', TIMESTAMP '2026-09-17 17:09:56');
        INSERT INTO "zing_doctor_db_prod"."quality_fact_def" ("id", "fact_name", "domain_code", "status", "source_table", "alias", "patient_key", "in_hospital_no_key", "patient_name_key", "depart_key", "select_cols", "derive_cols", "where_conds", "group_cols", "note", "operator", "create_time", "update_time") VALUES (178949848001600, 'fact_bed', '床位_资源', 'ACTIVE', 'config_bed', 'b', 'bed_id', 'in_hospital_no', 'patient_name', 'depart_code', '["b.id AS bed_id","b.bed_code AS bed_code","b.bed_name AS bed_name","b.depart_code AS depart_code","b.begin_use_time AS begin_use_time","b.stop_use_time AS stop_use_time"]', '["CASE WHEN b.begin_use_time IS NULL OR b.begin_use_time > :periodEnd THEN :periodEnd ELSE b.begin_use_time END AS open_to","DATEDIFF(DAY, CASE WHEN b.begin_use_time < :periodStart THEN :periodStart ELSE b.begin_use_time END, CASE WHEN (b.stop_use_time IS NULL OR b.stop_use_time > :periodEnd) THEN :periodEnd ELSE b.stop_use_time END) AS bed_days"]', '["b.del_flag = 0"]', '[]', '待接床位开放记录。缺该源，因此 quality_301/304 无法计算（页面显示「待接数据源」而非 0）', 'unknown', TIMESTAMP '2026-09-16 02:54:39', TIMESTAMP '2026-09-16 21:17:22');
        INSERT INTO "zing_doctor_db_prod"."quality_fact_def" ("id", "fact_name", "domain_code", "status", "source_table", "alias", "patient_key", "in_hospital_no_key", "patient_name_key", "depart_key", "select_cols", "derive_cols", "where_conds", "group_cols", "note", "operator", "create_time", "update_time") VALUES (178949848002000, 'fact_abx_culture', '抗菌药送检', 'ACTIVE', 'patient_info', 'pi', 'patient_id', 'in_hospital_no', 'patient_name', 'depart_code', '["pi.id AS patient_id","pi.in_hospital_no AS in_hospital_no","pi.name AS patient_name","pi.depart_code AS depart_code","pi.in_depart_time AS in_depart_time","pi.out_depart_time AS out_depart_time","pi.bed_code AS bed_code","CAST(pi.diagnosis_content AS VARCHAR(2000)) AS diagnosis_content"]', '["CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice\" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = ''1'' AND pa.type_code = ''drug'' AND (pa.name LIKE ''%头孢%'' OR pa.name LIKE ''%培南%'' OR pa.name LIKE ''%万古霉素%'' OR pa.name LIKE ''%利奈唑胺%'' OR pa.name LIKE ''%替考拉宁%'' OR pa.name LIKE ''%达托霉素%'' OR pa.name LIKE ''%左氧氟沙星%'' OR pa.name LIKE ''%莫西沙星%'' OR pa.name LIKE ''%环丙沙星%'' OR pa.name LIKE ''%阿奇霉素%'' OR pa.name LIKE ''%阿米卡星%'' OR pa.name LIKE ''%庆大霉素%'' OR pa.name LIKE ''%替加环素%'' OR pa.name LIKE ''%多黏菌素%'' OR pa.name LIKE ''%氟康唑%'' OR pa.name LIKE ''%伏立康唑%'' OR pa.name LIKE ''%卡泊芬净%'' OR pa.name LIKE ''%米卡芬净%'' OR pa.name LIKE ''%甲硝唑%'' OR pa.name LIKE ''%青霉素%'' OR pa.name LIKE ''%阿莫西林%'' OR pa.name LIKE ''%氨苄西林%'' OR pa.name LIKE ''%哌拉西林%'' OR pa.name LIKE ''%氨曲南%'' OR pa.name LIKE ''%磷霉素%'' OR pa.name LIKE ''%利福平%'' OR pa.name LIKE ''%磺胺%'' OR pa.name LIKE ''%新诺明%'')) THEN 1 ELSE 0 END AS abx_used","(SELECT MIN(pa.start_time) FROM \"zing_icu_db_prod\".\"patient_advice\" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = ''1'' AND pa.type_code = ''drug'' AND pa.start_time IS NOT NULL AND (pa.name LIKE ''%头孢%'' OR pa.name LIKE ''%培南%'' OR pa.name LIKE ''%万古霉素%'' OR pa.name LIKE ''%利奈唑胺%'' OR pa.name LIKE ''%替考拉宁%'' OR pa.name LIKE ''%达托霉素%'' OR pa.name LIKE ''%左氧氟沙星%'' OR pa.name LIKE ''%莫西沙星%'' OR pa.name LIKE ''%环丙沙星%'' OR pa.name LIKE ''%阿奇霉素%'' OR pa.name LIKE ''%阿米卡星%'' OR pa.name LIKE ''%庆大霉素%'' OR pa.name LIKE ''%替加环素%'' OR pa.name LIKE ''%多黏菌素%'' OR pa.name LIKE ''%氟康唑%'' OR pa.name LIKE ''%伏立康唑%'' OR pa.name LIKE ''%卡泊芬净%'' OR pa.name LIKE ''%米卡芬净%'' OR pa.name LIKE ''%甲硝唑%'' OR pa.name LIKE ''%青霉素%'' OR pa.name LIKE ''%阿莫西林%'' OR pa.name LIKE ''%氨苄西林%'' OR pa.name LIKE ''%哌拉西林%'' OR pa.name LIKE ''%氨曲南%'' OR pa.name LIKE ''%磷霉素%'' OR pa.name LIKE ''%利福平%'' OR pa.name LIKE ''%磺胺%'' OR pa.name LIKE ''%新诺明%'')) AS abx_first_time","(SELECT MIN(li.check_time) FROM \"zing_icu' || '_db_prod\".\"patient_info_lis_item\" li WHERE li.in_hospital_no = pi.in_hospital_no AND li.del_flag = 0 AND li.check_time IS NOT NULL AND (li.lis_item_name LIKE ''%培养%'' OR li.lis_item_name LIKE ''%涂片%'' OR li.lis_item_name LIKE ''%镜检%'' OR li.lis_item_name LIKE ''%药敏%'' OR li.lis_item_name LIKE ''%鉴定%'')) AS culture_first_time","(SELECT MIN(li.check_time) FROM \"zing_icu_db_prod\".\"patient_info_lis_item\" li WHERE li.in_hospital_no = pi.in_hospital_no AND li.del_flag = 0 AND li.check_time IS NOT NULL AND li.lis_item_name LIKE ''%降钙素原%'') AS pct_first_time","(SELECT MIN(li.check_time) FROM \"zing_icu_db_prod\".\"patient_info_lis_item\" li WHERE li.in_hospital_no = pi.in_hospital_no AND li.del_flag = 0 AND li.check_time IS NOT NULL AND (li.lis_item_name LIKE ''%G试验%'' OR li.lis_item_name LIKE ''%GM试验%'' OR li.lis_item_name LIKE ''%半乳甘露聚糖%'' OR li.lis_item_name LIKE ''%1,3-β-D葡聚糖%'')) AS ggm_first_time","(SELECT MIN(li.check_time) FROM \"zing_icu_db_prod\".\"patient_info_lis_item\" li WHERE li.in_hospital_no = pi.in_hospital_no AND li.del_flag = 0 AND li.check_time IS NOT NULL AND (li.lis_item_name LIKE ''%白介素%'' OR li.lis_item_name LIKE ''%IL-6%'' OR li.lis_item_name LIKE ''%IL6%'')) AS il6_first_time"]', '["pi.del_flag = 0","pi.in_depart_time IS NOT NULL","pi.in_depart_time < :periodEnd","(pi.out_depart_time IS NULL OR pi.out_depart_time >= :periodStart)"]', '[]', '首次抗菌药使用时间与首次各类病原学送检时间（比较口径在指标层）', 'seed', TIMESTAMP '2026-09-16 02:54:39', TIMESTAMP '2026-09-16 02:54:39');
        INSERT INTO "zing_doctor_db_prod"."quality_fact_def" ("id", "fact_name", "domain_code", "status", "source_table", "alias", "patient_key", "in_hospital_no_key", "patient_name_key", "depart_key", "select_cols", "derive_cols", "where_conds", "group_cols", "note", "operator", "create_time", "update_time") VALUES (178949848002400, 'fact_dvt', 'DVT预防', 'ACTIVE', 'patient_info', 'pi', 'patient_id', 'in_hospital_no', 'patient_name', 'depart_code', '["pi.id AS patient_id","pi.in_hospital_no AS in_hospital_no","pi.name AS patient_name","pi.gender AS gender","pi.bed_code AS bed_code","pi.age AS age","pi.depart_code AS depart_code","pi.ward_name AS ward_name","pi.out_vest_type AS out_vest_type","pi.charge_doctor_name AS charge_doctor_name","pi.in_depart_time AS in_depart_time","pi.out_depart_time AS out_depart_time","pi.out_hospital_time AS out_hospital_time","CAST(pi.diagnosis_content AS VARCHAR(2000)) AS diagnosis_content"]', '["CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%深静脉血栓%'' OR d.diag_name LIKE ''%下肢静脉血栓%'' OR d.diag_name LIKE ''%肺栓塞%'')) THEN 1 ELSE 0 END AS dvt_diag","CASE WHEN pi.out_vest_type = 3 AND EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%深静脉血栓%'' OR d.diag_name LIKE ''%下肢静脉血栓%'' OR d.diag_name LIKE ''%肺栓塞%'')) THEN 1 ELSE 0 END AS dvt_death","CASE WHEN pi.out_vest_type = 3 AND pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS died_in_period","CASE WHEN pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS out_in_period","(SELECT e.drug_name FROM \"zing_icu_db_prod\".\"patient_advice_execute_drug\" e WHERE e.patient_id = pi.id AND (e.drug_name LIKE ''%肝素%'' OR e.drug_name LIKE ''%达比加群酯%'' OR e.drug_name LIKE ''%利伐沙班%'') limit 1)  AS dvt_drug","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice_execute_drug\" e WHERE e.patient_id = pi.id AND (e.drug_name LIKE ''%肝素%'' OR e.drug_name LIKE ''%达比加群酯%'' OR e.drug_name LIKE ''%利伐沙班%'')) THEN 1 ELSE 0 END AS dvt_drug_status","(SELECT o.advice_name FROM \"zing_icu_db_prod\".\"patient_advice_original\" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND (o.advice_name LIKE ''%气压治疗%'' OR o.advice_name LIKE ''%运动疗法%'' OR o.advice_name LIKE ''%弹力袜%'') limit 1)  AS dvt_active","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice_original\" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND (o.advice_name LIKE ''%气压治疗%'' OR o.advice_name LIKE ''%运动疗法%'' OR o.advice_name LIKE ''%弹力袜%'')) THEN 1 ELSE 0 END AS dvt_active_status","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice_original\" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_n' || 'o AND o.advice_name LIKE ''%下腔静脉滤器置入%'' )THEN 1 ELSE 0 END AS dvt_shu"]', '["pi.del_flag = 0","pi.in_depart_time IS NOT NULL","pi.out_depart_time IS NOT NULL","pi.out_depart_time < :periodEnd","pi.out_depart_time >= :periodStart"]', '[]', 'DVT 由诊断文本识别；预防措施与滤器待接医嘱侧数据源', '系统管理员', TIMESTAMP '2026-09-16 02:54:39', TIMESTAMP '2026-09-17 16:42:08');
        INSERT INTO "zing_doctor_db_prod"."quality_fact_def" ("id", "fact_name", "domain_code", "status", "source_table", "alias", "patient_key", "in_hospital_no_key", "patient_name_key", "depart_key", "select_cols", "derive_cols", "where_conds", "group_cols", "note", "operator", "create_time", "update_time") VALUES (178949848002700, 'fact_device', '导管_管路_院感', 'PENDING_SOURCE', 'device_record', 'dv', 'patient_id', 'in_hospital_no', 'patient_name', 'depart_code', '["dv.id AS device_id","dv.patient_id AS patient_id","dv.in_hospital_no AS in_hospital_no","dv.patient_name AS patient_name","dv.depart_code AS depart_code","dv.device_type AS device_type","dv.insert_time AS insert_time","dv.remove_time AS remove_time","dv.remove_planned AS remove_planned","dv.infection_flag AS infection_flag"]', '["CASE WHEN dv.remove_time IS NOT NULL AND dv.remove_time >= :periodStart AND dv.remove_time < :periodEnd THEN 1 ELSE 0 END AS removed_in_period","CASE WHEN dv.remove_time IS NOT NULL AND dv.remove_planned = 0 THEN 1 ELSE 0 END AS unplanned_removal","CASE WHEN dv.infection_flag = 1 AND dv.insert_time >= :periodStart AND dv.insert_time < :periodEnd THEN 1 ELSE 0 END AS device_infection","DATEDIFF(DAY, CASE WHEN dv.insert_time < :periodStart THEN :periodStart ELSE dv.insert_time END, CASE WHEN (dv.remove_time IS NULL OR dv.remove_time > :periodEnd) THEN :periodEnd ELSE dv.remove_time END) AS device_days"]', '["dv.del_flag = 0","dv.insert_time < :periodEnd","(dv.remove_time IS NULL OR dv.remove_time >= :periodStart)"]', '[]', '待接管路/导管事件表（置入、拔除、是否计划拔管、是否相关感染）', 'seed', TIMESTAMP '2026-09-16 02:54:39', TIMESTAMP '2026-09-16 02:54:39');
    END IF;
    COMMIT;
END;
